### Complete Firebase Security Rules

Copy and paste the following rules into your Firebase Console under **Firestore Database > Rules**.

These rules ensure:
1.  **Badge Config**: Only admins can update the homepage badge (`config/homepage`), but anyone can read it.
2.  **Chat Privacy**: Users can only access their own chat sessions and messages.
3.  **Community**: Authenticated users can create posts. Users can only update/delete their own posts/comments.
4.  **Users**: Users can read other profiles but only update their own.
5.  **Admins**: Defined by specific UIDs, they can perform administrative actions.

```firestore-security-rules
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- HELPER FUNCTIONS ---

    // Check if user is authenticated
    function isAuthenticated() {
      return request.auth != null;
    }

    // Check if the user is the owner of the resource (userId matches auth.uid)
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }

    // Check if the user is an Admin (replace UIDs with actual admin UIDs)
    function isAdmin() {
      return isAuthenticated() && 
        (request.auth.uid == 'kMJDwlP0IDferEsOluQdqc9tQHI3' || 
         request.auth.uid == 'wEf4GdpgsBcIHaUSSTV5mPOy31H2');
    }

    // --- RULES ---

    // 1. CONFIG COLLECTION (Badge Text & Time)
    // Anyone can read the config (for homepage display).
    // Only Admins can write to it.
    match /config/{docId} {
      allow read: if true;
      allow write: if isAdmin();
    }

    // 2. USERS COLLECTION
    // Anyone can read profiles (needed for community feed avatars).
    // Only the user can create/update their own profile.
    // Only Admins can update projectStatus fields on any user.
    match /users/{userId} {
      allow read: if true;
      allow create: if isOwner(userId);
      allow update: if isOwner(userId) || isAdmin(); 

      // Subcollections for saved/liked posts
      match /savedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }
      match /likedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }

      // Chat Sessions (Nested under users in your structure, or separate?)
      // Based on your code: `artifacts/{appId}/users/{userId}/sessions`
    }

    // 3. COMMUNITY POSTS
    // Anyone can read posts.
    // Auth users can create.
    // Authors or Admins can delete/update.
    match /community-posts/{postId} {
      allow read: if true;
      allow create: if isAuthenticated();
      allow update, delete: if isAuthenticated() && (resource.data.author.id == request.auth.uid || isAdmin());
    }

    // 4. COMMENTS & REPLIES
    // Anyone can read.
    // Auth users can create.
    // Authors or Admins can delete.
    match /usercomments/{commentId} {
      allow read: if true;
      allow create: if isAuthenticated();
      allow update, delete: if isAuthenticated() && (resource.data.author.id == request.auth.uid || isAdmin());
    }

    // 5. CHAT ARTIFACTS (Chat History)
    // Strictly private. Only the owner can read/write their sessions.
    match /artifacts/{appId}/users/{userId}/sessions/{sessionId} {
      allow read, write: if isOwner(userId);

      match /messages/{messageId} {
        allow read, write: if isOwner(userId);
      }
    }
  }
}

