Here are the Firebase Security Rules you requested. You can paste these directly into your Firebase Console under **Firestore Database > Rules**.

### **Complete Firebase Security Rules**

These rules handle the **Admin-only** badge configuration updates while allowing everyone to read them. They also secure user data, community posts, and private chat sessions.

```firestore-security-rules
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- HELPER FUNCTIONS ---

    // Check if user is authenticated
    function isAuthenticated() {
      return request.auth != null;
    }

    // Check if the user is the owner of the resource
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }

    // Check if the user is an Admin
    // REPLACE these strings with your actual Admin User UIDs from Firebase Auth
    function isAdmin() {
      return isAuthenticated() && 
        (request.auth.uid == 'kMJDwlP0IDferEsOluQdqc9tQHI3' || 
         request.auth.uid == 'wEf4GdpgsBcIHaUSSTV5mPOy31H2');
    }

    // --- RULES ---

    // 1. CONFIG COLLECTION (Homepage Badge)
    // Everyone can read the badge text/time.
    // Only Admins can write (update text or reset time).
    match /config/{docId} {
      allow read: if true;
      allow write: if isAdmin();
    }

    // 2. USERS COLLECTION
    // Profiles are public (read: true) for the community feed.
    // Users can only edit their own profile.
    // Admins can update projectStatus on any profile.
    match /users/{userId} {
      allow read: if true;
      allow create: if isOwner(userId);
      allow update: if isOwner(userId) || isAdmin(); 

      // Private subcollections for bookmarks/likes
      match /savedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }
      match /likedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }
    }

    // 3. COMMUNITY POSTS
    // Publicly readable.
    // Authenticated users can create.
    // Only the Author or an Admin can update/delete.
    match /community-posts/{postId} {
      allow read: if true;
      allow create: if isAuthenticated();
      allow update, delete: if isAuthenticated() && (resource.data.author.id == request.auth.uid || isAdmin());
    }

    // 4. COMMENTS & REPLIES
    // Same rules as posts.
    match /usercomments/{commentId} {
      allow read: if true;
      allow create: if isAuthenticated();
      allow update, delete: if isAuthenticated() && (resource.data.author.id == request.auth.uid || isAdmin());
    }

    // 5. CHAT ARTIFACTS (AI Chat History)
    // Strictly private. Only the owner can read/write their sessions.
    match /artifacts/{appId}/users/{userId}/sessions/{sessionId} {
      allow read, write: if isOwner(userId);

      match /messages/{messageId} {
