### **1. Firestore Security Rules**
Copy and paste these rules into your **Firebase Console > Firestore Database > Rules** tab.

```javascript
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- HELPER FUNCTIONS ---
    function isSignedIn() {
      return request.auth != null;
    }
    function isOwner(userId) {
      return isSignedIn() && request.auth.uid == userId;
    }

    // --- USERS COLLECTION ---
    match /users/{userId} {
      allow read: if true;

      // CREATE: User can create their own profile
      allow create: if isOwner(userId);

      // UPDATE: 
      // 1. User can update their own profile
      // 2. OTHERS can only update 'followersCount' (increment/decrement by 1)
      //    This enables the "Follow" feature to work securely.
      allow update: if isOwner(userId) || 
                    (isSignedIn() && 
                     request.resource.data.diff(resource.data).affectedKeys().hasOnly(['followersCount']) &&
                     math.abs(request.resource.data.followersCount - resource.data.followersCount) == 1
                    );

      // --- FOLLOW SYSTEM ---

      // 1. Following: Private list of who I follow
      match /following/{targetId} {
        allow read, write: if isOwner(userId);
      }

      // 2. Followers: Public list of who follows me
      // Key concept: The ID of the document is the ID of the FOLLOWER.
      // So checking 'isOwner(followerId)' ensures users can only add THEMSELVES as a follower.
      match /followers/{followerId} {
        allow read: if true;
        allow write: if isOwner(followerId);
      }

      // --- USER PRIVATE LISTS ---
      match /savedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }
      match /likedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }
    }

    // --- POSTS COLLECTION ---
    match /community-posts/{postId} {
      allow read: if true;
      allow create: if isSignedIn() && request.resource.data.author.id == request.auth.uid;
      allow update: if isSignedIn() && (
          // Author can update their post
          resource.data.author.id == request.auth.uid ||
          // Others can only update likeCount/repostCount/commentCount/poll
          request.resource.data.diff(resource.data).affectedKeys().hasOnly(['likeCount', 'repostCount', 'commentCount', 'poll'])
      );
      allow delete: if isSignedIn() && (resource.data.author.id == request.auth.uid || 
                    // Optional: Add admin UIDs here
                    request.auth.uid in ['kMJDwlP0IDferEsOluQdqc9tQHI3', 'wEf4GdpgsBcIHaUSSTV5mPOy31H2']);
    }

    // --- COMMENTS COLLECTION ---
    match /usercomments/{commentId} {
      allow read: if true;
      allow create: if isSignedIn() && request.resource.data.author.id == request.auth.uid;
      allow update, delete: if isSignedIn() && request.resource.data.author.id == request.auth.uid;
    }

    // --- CONFIG COLLECTION (For Homepage Badge) ---
    match /config/{docId} {
      allow read: if true;
      allow write: if isSignedIn() && request.auth.uid in ['kMJDwlP0IDferEsOluQdqc9tQHI3', 'wEf4GdpgsBcIHaUSSTV5mPOy31H2'];
