        allow read, write: if isOwner(userId);
      }

      // Liked Posts: Private to owner
      match /likedPosts/{postId} {
        allow read, write: if isOwner(userId);
      }
    }

    // --- Community Posts ---
    match /community-posts/{postId} {
      allow read: if true;
      allow create: if isAuthenticated() && request.resource.data.author.id == request.auth.uid;

      // Allow author or admin to delete
      allow delete: if isAuthenticated() && (resource.data.author.id == request.auth.uid || isAdmin());

      // Allow interactions (likes, comments, reposts, polls) by any auth user
      allow update: if isAuthenticated() && (
         request.resource.data.diff(resource.data).affectedKeys().hasAny(['likeCount', 'commentCount', 'repostCount', 'poll'])
      );
    }

    // --- Comments ---
    match /usercomments/{commentId} {
      allow read: if true;
      allow create: if isAuthenticated() && request.resource.data.author.id == request.auth.uid;

      // Update replyCount
      allow update: if isAuthenticated() && (
        isOwner(resource.data.author.id) || 
        request.resource.data.diff(resource.data).affectedKeys().hasOnly(['replyCount'])
      );

      allow delete: if isAuthenticated() && (resource.data.author.id == request.auth.uid || isAdmin());
    }

    // --- Chat (Private) ---
    match /artifacts/{appId}/users/{userId}/sessions/{sessionId} {
      allow read, write: if isOwner(userId);

      match /messages/{messageId} {
        allow read, write: if isOwner(userId);
      }
    }

    // --- Configuration (Admin) ---
    match /config/{docId} {
      allow read: if true;
      allow write: if isAdmin();
    }
  }
}
```

